namespace App\Support;

/**
 * Ikon SVG inline untuk navigasi sidebar dan kartu menu cepat.
 *
 * Path data diambil dari Bootstrap Icons (MIT, https://icons.getbootstrap.com)
 * sehingga tidak ada dependensi package baru. Semua ikon memakai
 * viewBox 16x16 dan fill="currentColor" agar mewarisi warna teks.
 */
class NavIcon
{
    /**
     * Render ikon sebagai string SVG inline.
     *
     * @param  array<string, string>  $attrs  Atribut tambahan untuk tag <svg>.
     */
    public static function svg(string $key, array $attrs = []): string
    {
        $paths = static::paths();
        $inner = $paths[$key] ?? $paths['circle'];

        $defaults = [
            'xmlns' => 'http://www.w3.org/2000/svg',
            'width' => '16',
            'height' => '16',
            'fill' => 'currentColor',
            'viewBox' => '0 0 16 16',
            'aria-hidden' => 'true',
            'focusable' => 'false',
        ];

        $attrs = array_merge($defaults, $attrs);

        $rendered = '';
        foreach ($attrs as $name => $value) {
            $rendered .= ' '.$name.'="'.htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8').'"';
        }

        return '<svg'.$rendered.'>'.$inner.'</svg>';
    }

